CREATE TABLE execution_delegations(schedule_id uuid PRIMARY KEY REFERENCES schedules(id) DEFERRABLE,owner_id uuid NOT NULL REFERENCES owners(id),epoch integer NOT NULL,host_id uuid REFERENCES host_nodes(id) DEFERRABLE,pending_host_id uuid REFERENCES host_nodes(id) DEFERRABLE,pending_executor text,state text NOT NULL DEFAULT 'active',lease_until timestamptz,revocation_ack boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1);
CREATE TABLE reply_relays(owner_id uuid PRIMARY KEY REFERENCES owners(id),link_id uuid REFERENCES host_identity_links(id) DEFERRABLE,enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1);
CREATE TABLE host_plugins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),host_id uuid NOT NULL REFERENCES host_nodes(id) DEFERRABLE,install_id uuid NOT NULL REFERENCES extension_installs(id) DEFERRABLE,network jsonb NOT NULL DEFAULT '[]',directories jsonb NOT NULL DEFAULT '[]',budget jsonb NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1);
ALTER TABLE host_jobs ADD COLUMN relay_run_id uuid REFERENCES runs(id) DEFERRABLE;
ALTER TABLE runs DROP CONSTRAINT runs_state_check;
ALTER TABLE runs ADD CONSTRAINT runs_state_check CHECK(state IN ('queued','running','completed','failed','cancelled','interrupted','awaiting_approval','remote_pending'));
